def main():
    ap=argparse.ArgumentParser(description=__doc__)
    for n in ('private','local','prior-closure','previous-inspection','scope','output','candidate-install'):
        ap.add_argument('--'+n,type=Path,required=True)
    a=ap.parse_args();a.output.mkdir()
    me=psutil.Process();owner=dict(pid=me.pid,create_time=me.create_time(),affinity=[14])
    def put(name,raw):
        with (a.output/name).open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
        if (a.output/name).read_bytes()!=raw:raise IOError('Exact inspection readback')
    def save(name,value):put(name,(json.dumps(value,sort_keys=True,indent=2)+'\n').encode())
    save('REGISTERED_OWNER.json',owner)
    scope=json.loads(a.scope.read_bytes());last_guard=[0.]
    def guard():
        now=datetime.now(timezone.utc)
        if now>=datetime.fromisoformat(scope['expires_utc']):raise TimeoutError('Host scope expired')
        if now>=datetime(2026,10,2,14,14,20,tzinfo=timezone.utc):raise TimeoutError('User deadline')
        if time.monotonic()-last_guard[0]<2:return
        last_guard[0]=time.monotonic()
        if sum(p.stat().st_size for p in a.scope.parent.rglob('*') if p.is_file())+1048576>scope['maximum_bytes']:raise ValueError('Full metadata reserve')
        if shutil.disk_usage('C:/').free<50*1024**3 or shutil.disk_usage('G:/').free<75*1024**3:raise RuntimeError('Host floors')
    guard()
    from field_runtime_host_precheck_v2 import inspect
    pre,details=inspect(a.local,a.private,current_owner=owner,deadline=time.monotonic()+100,guard=guard)
    save('HOST_PRECHECK.json',pre);save('HOST_PRECHECK_DETAILS.json',details)
    if pre['alive_owners']:raise RuntimeError('Other live host owner; leave it untouched')
    # Actual route GET bytes independently copied and read back before mutation.
    cap_raw=(a.previous_inspection/'RESULT.json').read_bytes();cap=json.loads(cap_raw)
    route=cap['raw_route_capability']
    if route['route_mutated'] or route['control_protocol']!='i2c':raise ValueError('Actual read-only I2C prerequisite')
    def numbers(text):
        import re
        return [int(re.fullmatch(r'[A-Z_]+\[(\d+)\]',p).group(1)) if '[' in p else int(p) for p in text.split()[1:]]
    raw_routes={q['command']:numbers(q['result']['stdout']) for q in route['queries'] if q['command'] in ('AUDIO_MGR_OP_ALL','AUDIO_MGR_OP_PACKED')}
    if raw_routes!={'AUDIO_MGR_OP_ALL':[8,0,1,0,1,2,0,0,1,1,1,3],'AUDIO_MGR_OP_PACKED':[0,0]}:raise ValueError('Exact current route prerequisite')
    restore=dict(routes=raw_routes,host_tool_pin=route['host_tool_pin'])
    put('DEVICE_ROUTE_BACKUP.json',cap_raw);put('DEVICE_ROUTE_RESTORE.json',cap_raw)
    if (a.output/'DEVICE_ROUTE_BACKUP.json').read_bytes()!=(a.output/'DEVICE_ROUTE_RESTORE.json').read_bytes():raise IOError('Route restore readback')
    sys.path.insert(0,str(Path(__file__).parent.parent))
    from window_guard import payload_inventory
    inventory=payload_inventory(a.local)
    if inventory['errors']:raise RuntimeError('Incomplete host payload census')
    prior_census=json.loads((a.local/'n5/d1-anonymous-lifecycle-parent-v4/ADMISSION.json').read_bytes())['census']
    old_bytes=Path(prior_census['path']).read_bytes()
    if hashlib.sha256(old_bytes).hexdigest()!=prior_census['sha256']:raise ValueError('Original census pin')
    if set(inventory['reparse_not_traversed'])!=set(json.loads(old_bytes)['inventory']['reparse_not_traversed']):raise ValueError('Reparse inventory drift')
    used=0
    for rel in ('n5/prepi-20260928','releases/prepi-shutdown-v1','n5/listening-examples-v1','n5/research-extension-20260928'):
        part=payload_inventory(a.local/rel)
        if part['errors'] or part['reparse_not_traversed']:raise ValueError('Incomplete output census')
        used+=part['total_logical_bytes']
    mib=1048576;target_ceiling=cap['target_bytes']+mib
    budget=dict(issued_utc=datetime.now(timezone.utc).isoformat(),expires_utc=scope['expires_utc'],
       host_output_bytes=used,host_payload_bytes=inventory['total_logical_bytes'],target_ceiling_bytes=target_ceiling,new_host_bytes=2*mib,new_target_bytes=0,
       combined_output_cap=((used+target_ceiling+2*mib+8*mib+mib-1)//mib)*mib,
       payload_cap=((inventory['total_logical_bytes']+2684354560+target_ceiling+2*mib+8*mib+mib-1)//mib)*mib,
       duration_seconds=12,retained_transport_seconds_maximum=0.201,maximum_output_bytes=262144,
       original_window_unchanged=True,failed_deleted_unused_credit=False,independent_backups=True,
       inventory_sha256=hashlib.sha256(json.dumps(inventory,sort_keys=True).encode()).hexdigest())
    save('RAW_PAIR_RESOURCE_POLICY.json',budget)
    prior_raw=a.prior_closure.read_bytes();old=json.loads(prior_raw);identities={}
    for row in old['owners']+old['additional_registered_owners']:
        v={k:row['owner'][k] for k in ('pid','start_ticks','boot_id')};identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    v=old['utility_owner'];identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    previous=json.loads((a.previous_inspection/'NATIVE_OWNER.json').read_bytes())
    from field_local_manager_owners_v1 import identity
    identity(previous);identities[(previous['boot_id'],previous['pid'],previous['start_ticks'])]=previous
    issued=json.loads((a.candidate_install/'ADMISSION.json').read_bytes())
    installed=json.loads((a.candidate_install/'RESULT.json').read_bytes())
    if issued['root']!=installed['root'] or hashlib.sha256((a.candidate_install/'RELEASE.json').read_bytes()).hexdigest()!=installed['policy_sha256']:
        raise ValueError('Exact issued candidate prior-owner binding')
    for row in issued['prior']:
        v=identity(row);identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    later=list(a.scope.parent.glob('install-inspection-v*/NATIVE_OWNER.json'))+list(a.private.glob('runtime-titanet-v*-install/NATIVE_OWNER.json'))+list(a.private.glob('runtime-titanet-v*-install/CLOSURE_OWNER.json'))
    later=[p for p in later if tuple(identity(json.loads(p.read_bytes()))[k] for k in ('boot_id','pid','start_ticks')) not in identities]
    if len(later)>16:raise ValueError('Bounded explicit inspection continuation owners')
    for path in later:
        v=identity(json.loads(path.read_bytes()))
        identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    assert len(identities)<=1024
    historical={row['path'].split('/nemotron-20260928/',1)[1]:row['owner'] for row in old['owners']
        if set(row['owner'])!={'pid','start_ticks','boot_id'}}
    nested={}
    for row in old['owners']:
        rel=Path(row['path']).as_posix().split('/nemotron-20260928/',1)[-1]
        if rel.startswith('field-local-release-v') and '/launches/' in rel:
            mirrored=a.private/('field-local-release-v1-admission' if rel.startswith('field-local-release-v1/') else 'field-local-release-v2-admission')
    # Exact immutable historical envelope pins from the selected collector.
    nested={
      'field-local-release-v1/launches/launch-01/OWNER.json':dict(sha256='6fe6f5b378e2ef6c66f89b8cf32cb75c93f7f7216a4e1454d1bacb2030707fbe',policy_sha256='d8600a564dc41641ab799b1f64dc977a9ef719c8c3a45847d00cd6a5023dd454',slot='launches/launch-01',purpose='METADATA_QUALIFICATION_ONLY'),
      'field-local-release-v1/launches/launch-02/OWNER.json':dict(sha256='2c3dbd0f2c4c6a9e80499346a4fac8a306865ea759849786993850fe4e65bc15',policy_sha256='d8600a564dc41641ab799b1f64dc977a9ef719c8c3a45847d00cd6a5023dd454',slot='launches/launch-02',purpose='METADATA_QUALIFICATION_ONLY')}
    collector=(Path(__file__).parent/'collect_native_closure_v19.py').read_text(encoding='utf-8')
    # Extract only its literal native source constant; no collector execution.
    constants=[n.value for n in ast.walk(ast.parse(collector)) if isinstance(n,ast.Constant) and isinstance(n.value,str) and 'NEW_NESTED=' in n.value]
    if len(constants)!=1:raise ValueError('Selected historical collector boundary')
    native_tree=ast.parse(constants[0])
    assignment=next(n for n in native_tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='NEW_NESTED' for t in n.targets))
    for path,row in ast.literal_eval(assignment.value).items():
        nested[path]={**row,'policy_sha256':'f39a8b7dbedbebed1492687d42d5648ac033dbba0d02a4a46537175e1fa40d9c'}
    candidate_admission=json.loads((a.candidate_install/'ADMISSION.json').read_bytes())
    for path,row in candidate_admission['nested'].items():
        if path in nested and nested[path]!=row:raise ValueError('Historical owner conflict')
        nested[path]=row
    candidate_result=json.loads((a.candidate_install/'RESULT.json').read_bytes())
    rid=Path(candidate_result['root']).name
    policy_sha=hashlib.sha256((a.candidate_install/'RELEASE.json').read_bytes()).hexdigest()
    if candidate_result['policy_sha256']!=policy_sha or candidate_result['root']!=candidate_admission['root']:
        raise ValueError('Exact installed candidate admission/result')
    for path in a.private.glob('field-runtime-v*-install/NATIVE_CLOSURE.json'):
        proof=json.loads(path.read_bytes())
        if proof['exact_owner_dead'] is not True or proof['utility_pid_absent'] is not True:raise ValueError('Actual installer closure')
        for k in ('owner','utility_owner'):
            v=proof[k];identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    for path in list(a.scope.parent.glob('candidate*/NATIVE_OWNER.json'))+list(a.private.glob('field-runtime-v*-preservation*/NATIVE_OWNER.json'))+list(a.private.glob('field-runtime-v*-offload*/NATIVE_OWNER.json')):
        v=identity(json.loads(path.read_bytes()));identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    for path in a.private.glob('field-runtime-v*/NATIVE_OWNER.json'):
        v=identity(json.loads(path.read_bytes()));identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    if len(identities)>1024:raise ValueError('Bounded full prior owner set')
    for path in a.private.glob('field-runtime-v*-raw-pair-v*/ARECORD_OWNER.json'):
        v=identity(json.loads(path.read_bytes()));identities[(v['boot_id'],v['pid'],v['start_ticks'])]=v
    if len(identities)>1024:raise ValueError('Complete prior owner bound')
    guard()
    if datetime.now(timezone.utc)+timedelta(seconds=180)>=datetime.fromisoformat(scope['expires_utc']):raise TimeoutError('Complete read-only closure reserve')
    code='PRIOR='+repr(list(identities.values()))+'\nPRIOR_SHA='+repr(hashlib.sha256(prior_raw).hexdigest())+'\nNESTED='+repr(nested)+'\nHISTORICAL='+repr(historical)+'\nRID='+repr(rid)+'\nPOLICY_SHA='+repr(policy_sha)+'\nROUTE_BACKUP='+repr(restore)+'\nBUDGET='+repr(budget)+'\n'+NATIVE
    compile(code,'<runtime-install-inspection>','exec')
    save('CAPTURE_ADMISSION.json',dict(issued_utc=datetime.now(timezone.utc).isoformat(),expires_utc=scope['expires_utc'],
        maximum_seconds=165,maximum_output_bytes=262144,native_writes=False,capture=True,firmware_reset=False,playback=False,resource_policy=budget,precheck_sha256=hashlib.sha256((a.output/'HOST_PRECHECK.json').read_bytes()).hexdigest(),source_sha256=hashlib.sha256(code.encode()).hexdigest()))
    from field_operator_broker_host_v2 import ssh_phase,process_phase
    from dispatch_b01_stack_v2 import SSH
    argv=['systemd-run','--user','--quiet','--pipe','--wait','--collect','--unit=jp-runtime-raw-pair-v3','--slice=jpfield'+rid.replace('-','')+'.slice',
      '--property=Description=JustPeachyRawPairProbe','--property=AllowedCPUs=2-3','--property=CPUQuota=200%','--property=TasksMax=64',
      '--property=LimitAS=134217728','--property=LimitSTACK=1048576','--property=LimitFSIZE=0','--property=RuntimeMaxSec=180','--property=TimeoutStopSec=15',
      '/usr/bin/python3','-u','-B','-']
    result=ssh_phase(argv,payload=code.encode(),timeout=165,maximum=262144)
    out=result.pop('stdout');err=result.pop('stderr')
    put('STDOUT.bin',out);put('STDERR.bin',err);save('PHASE.json',result)
    native_owner=None
    if err.splitlines():
        native_owner=json.loads(err.splitlines()[0])['utility_owner'];save('NATIVE_OWNER.json',native_owner)
    if native_owner is None:raise RuntimeError('Missing early native identity; raw failure preserved')
    closed=process_phase(SSH+['test ! -e /proc/'+str(native_owner['pid'])],timeout=10,maximum=16384)
    cout=closed.pop('stdout');cerr=closed.pop('stderr')
    put('CLOSURE_STDOUT.bin',cout);put('CLOSURE_STDERR.bin',cerr);save('CLOSURE_PHASE.json',closed)
    if closed['returncode'] or closed['fault'] is not None or not closed['readers_joined'] or not closed['ssh_reaped']:raise RuntimeError('Exact inspector closure not certified')
    save('NATIVE_CLOSURE.json',dict(owner=native_owner,exact_pid_absent=True,natural_returncode=result['returncode']))
    if result['returncode'] or result['fault'] is not None or not result['readers_joined'] or not result['ssh_reaped']:
        raise RuntimeError('Preserved native read-only failure; inspector absence independently checked')
    value=json.loads(out)
    if value['utility_owner']!=native_owner or any('raw_route_phase' not in json.loads(line) for line in err.splitlines()[1:]):raise ValueError('Actual early identity')
    value['utility_pid_absent_after_ssh']=True
    value['prior_failed_inspector_checked_dead']=previous
    phase=value['raw_pair_probe'];child=phase['capture']['child_owner']
    save('ARECORD_OWNER.json',child)
    if phase['error'] or phase['capture']['child_returncode']!=0 or phase['capture']['stderr'] or phase['capture']['errors']:
        save('FAILED_RESULT.json',value);raise RuntimeError('Finite native raw capture failed; raw preserved')
    if phase['route_restoration']!={'AUDIO_MGR_OP_PACKED':'RESTORED','AUDIO_MGR_OP_ALL':'RESTORED'}:
        save('FAILED_RESULT.json',value);raise RuntimeError('Exact route restoration incomplete')
    child_closed=process_phase(SSH+['test ! -e /proc/'+str(child['pid'])],timeout=10,maximum=16384)
    co=child_closed.pop('stdout');ce=child_closed.pop('stderr')
    put('ARECORD_CLOSURE_STDOUT.bin',co);put('ARECORD_CLOSURE_STDERR.bin',ce);save('ARECORD_CLOSURE.json',child_closed)
    if child_closed['returncode'] or child_closed['fault'] or not child_closed['readers_joined'] or not child_closed['ssh_reaped']:raise RuntimeError('Capture child closure')
    import base64
    raw=base64.b64decode(phase['selected_base64'],validate=True)
    if len(raw)!=phase['capture']['bytes'] or hashlib.sha256(raw).hexdigest()!=phase['capture']['sha256']:raise ValueError('Actual captured bytes pin')
    for name in ('PACKED_S32LE.bin','PACKED_S32LE.restore.bin'):put(name,raw)
    save('RESULT.json',value)
    if sum(p.stat().st_size for p in a.output.rglob('*') if p.is_file())>budget['new_host_bytes']:raise RuntimeError('Full host bound')

    print(json.dumps({k:value[k] for k in ('utc','status','candidate_unit','candidate_ui','available_ram_bytes','target_free_bytes','native_writes')}))


if __name__=='__main__':main()
